#!/bin/sh
# Rebuild the transcript bundle with the current kit (level 20): the session log as recorded, and the
# instruction files collected. The instruction files are read from a staged copy whose bodies are redacted
# (tools/stage.py); the files in the real config directory are never changed.
S=${S:?set S to the scratch directory that holds fetched/ and stage/}
python3 -I "$S/tools/stage.py" "$S/stage/claude" >/dev/null && rm -rf "$S/stage/claude/projects" \
  && mv "$S"/stage/claude/skills/synced/*_* "$S/stage/claude/skills/synced/account" || exit 1
cd "$S/fetched/kitnow/token-radar-01-kit" && CLAUDE_CONFIG_DIR="$S/stage/claude" node cli/makefun.mjs bundle --repo /home/user/make-fun --out /home/user/make-fun/token-radar-01/transcripts.tar.gz "$@" \
  --mcp "Firecrawl=https://mcp.firecrawl.dev/v2/mcp" --mcp "github=https://api.githubcopilot.com/mcp/" --mcp "claude-code-remote=https://claude.ai/code" \
  --notes "Built in Claude Code on the web, a cloud session. That harness mounts its MCP servers itself and gives the session no MCP config to read, so the endpoints here are the nearest public ones: Firecrawl is the account's claude.ai connector, recorded at Firecrawl's documented hosted endpoint; github is the GitHub MCP server the harness provides through its own repository-scoped proxy, recorded at the upstream server's public endpoint; claude-code-remote is the harness's own session and environment server, which has no public endpoint, recorded at the product that mounts it. Firecrawl fetched make.fun's skill.md and the bounty page and looked up its own endpoint; github listed branches; claude-code-remote read environment docs. None wrote any of the entry's code. The 15 instruction files are stock skills the harness syncs to the account (document, browser and research skills, and a session-start-hook skill): none was written for this build and the build invoked none of them. Each is uploaded with its name and description and its body redacted, as the rules allow: the text is its publisher's, not the entrant's to pass on. The one skill the build did use, the impeccable design plugin, was loaded in-session and is in the transcript." 2>&1 | grep -v "searching \|scanning " | sed -E 's/af_[A-Za-z0-9_-]+/af_***/g; s/AF-[A-Za-z0-9-]+/AF-***/g' | cut -c1-260
